-- TOC entry 545 (class 1255 OID 145575)
-- Name: get_pending_initialization_stats(); Type: FUNCTION; Schema: audit_logging; Owner: postgres
--

CREATE FUNCTION audit_logging.get_pending_initialization_stats() RETURNS TABLE(status text, count bigint, oldest_created_at timestamp with time zone, newest_created_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    AS $$
    SELECT
        pui.status,
        COUNT(*) AS count,
        MIN(pui.created_at) AS oldest_created_at,
        MAX(pui.created_at) AS newest_created_at
    FROM audit_logging.pending_user_initializations pui
    GROUP BY pui.status
    ORDER BY pui.status;
$$;


