--
-- TOC entry 663 (class 1255 OID 144294)
-- Name: add_conversation_participant(uuid, uuid, character varying, uuid); Type: FUNCTION; Schema: communication; Owner: postgres
--

CREATE FUNCTION communication.add_conversation_participant(p_conversation_id uuid, p_user_id uuid, p_role character varying DEFAULT 'member'::character varying, p_added_by uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_participant_id UUID;
BEGIN
    -- Check if already a participant
    SELECT id INTO v_participant_id
    FROM communication.conversation_participants
    WHERE conversation_id = p_conversation_id
      AND user_id = p_user_id;

    IF v_participant_id IS NOT NULL THEN
        -- Reactivate if was deactivated
        UPDATE communication.conversation_participants
        SET is_active = TRUE,
            left_at = NULL,
            role = COALESCE(p_role, role),
            updated_at = NOW()
        WHERE id = v_participant_id;

        RETURN v_participant_id;
    END IF;

    -- Insert new participant
    INSERT INTO communication.conversation_participants (
        conversation_id,
        user_id,
        role
    ) VALUES (
        p_conversation_id,
        p_user_id,
        COALESCE(p_role, 'member')
    )
    RETURNING id INTO v_participant_id;

    RETURN v_participant_id;
END;
$$;


