--
-- TOC entry 682 (class 1255 OID 141689)
-- Name: update_teacher_contents_timestamp(); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.update_teacher_contents_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = NOW();

    -- Auto-set published_at when status changes to published
    IF NEW.status = 'published' AND OLD.status != 'published' THEN
        NEW.published_at = NOW();
    END IF;

    -- Increment times_assigned when target_classrooms changes
    IF NEW.target_classrooms IS DISTINCT FROM OLD.target_classrooms THEN
        NEW.times_assigned = COALESCE(OLD.times_assigned, 0) +
            (jsonb_array_length(NEW.target_classrooms) - jsonb_array_length(COALESCE(OLD.target_classrooms, '[]'::jsonb)));
    END IF;

    RETURN NEW;
END;
$$;


