--
-- TOC entry 645 (class 1255 OID 145454)
-- Name: apply_xp_boost(uuid, integer); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.apply_xp_boost(p_user_id uuid, p_base_xp integer) RETURNS TABLE(base_xp integer, total_multiplier numeric, boosted_xp integer, active_boosts_count integer)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_multiplier NUMERIC(4,2) := 1.0;
    v_boost_count INTEGER := 0;
BEGIN
    -- Calcular multiplicador total de XP
    SELECT
        COALESCE(SUM(multiplier - 1.0), 0.0) + 1.0,
        COUNT(*)
    INTO v_multiplier, v_boost_count
    FROM gamification_system.active_boosts
    WHERE user_id = p_user_id
      AND boost_type = 'XP'
      AND is_active = true
      AND expires_at > NOW();

    RETURN QUERY SELECT
        p_base_xp,
        v_multiplier,
        (p_base_xp * v_multiplier)::INTEGER,
        v_boost_count;
END;
$$;


