--
-- TOC entry 719 (class 1255 OID 145407)
-- Name: audit_profile_changes(); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.audit_profile_changes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_error_message TEXT;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        -- Log role changes
        IF OLD.role != NEW.role THEN
            INSERT INTO audit_logging.audit_logs (
                event_type,
                action,
                resource_type,
                resource_id,
                actor_id,
                old_values,
                new_values,
                description
            ) VALUES (
                'role_changed',
                'UPDATE',
                'profile',
                NEW.id,
                NEW.id,
                jsonb_build_object('role', OLD.role),
                jsonb_build_object('role', NEW.role),
                format('User role changed from %s to %s', OLD.role, NEW.role)
            );
        END IF;

        -- Log status changes
        IF OLD.status != NEW.status THEN
            INSERT INTO audit_logging.audit_logs (
                event_type,
                action,
                resource_type,
                resource_id,
                actor_id,
                old_values,
                new_values,
                description
            ) VALUES (
                'status_changed',
                'UPDATE',
                'profile',
                NEW.id,
                NEW.id,
                jsonb_build_object('status', OLD.status),
                jsonb_build_object('status', NEW.status),
                format('User status changed from %s to %s', OLD.status, NEW.status)
            );
        END IF;
    END IF;

    RETURN NEW;

EXCEPTION
    WHEN OTHERS THEN
        -- P1-001: Capturar error de auditoría sin bloquear operación
        v_error_message := SQLERRM;
        RAISE WARNING '[P1-001] Error en auditoría de cambio de perfil %: %', NEW.id, v_error_message;
        -- Auditoría no es crítica, no bloquear la operación original
        RETURN NEW;
END;
$$;


