-- TOC entry 620 (class 1255 OID 145409)
-- Name: get_current_user_role(); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.get_current_user_role() RETURNS auth_management.gamilit_role
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_role auth_management.gamilit_role;
BEGIN
    SELECT role INTO v_role
    FROM auth_management.profiles
    WHERE id = gamilit.get_current_user_id();

    RETURN v_role;
END;
$$;


