--
-- TOC entry 735 (class 1255 OID 145427)
-- Name: initialize_user_missions(uuid); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.initialize_user_missions(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_today_start TIMESTAMP;
    v_today_end TIMESTAMP;
    v_week_end TIMESTAMP;
    v_error_message TEXT;
    v_error_detail TEXT;
    v_error_code TEXT;
    -- REC-009: Template UUID variables (looked up from mission_templates)
    v_tpl_daily_exercises UUID;
    v_tpl_daily_earn_xp UUID;
    v_tpl_daily_use_comodin UUID;
    v_tpl_weekly_complete_module UUID;
    v_tpl_weekly_daily_streak UUID;
    v_tpl_weekly_perfect_scores UUID;
    v_tpl_weekly_explorer UUID;
    v_tpl_weekly_master_learner UUID;
BEGIN
    -- Calculate mission date ranges using Mexico timezone
    v_today_start := gamilit.now_mexico()::date;
    v_today_end := v_today_start + INTERVAL '23 hours 59 minutes';
    v_week_end := v_today_start + INTERVAL '7 days';

    -- REC-009: Look up template UUIDs from mission_templates by type + target_type
    SELECT id INTO v_tpl_daily_exercises FROM gamification_system.mission_templates
        WHERE type = 'daily' AND target_type = 'complete_exercises' AND is_active = true LIMIT 1;
    SELECT id INTO v_tpl_daily_earn_xp FROM gamification_system.mission_templates
        WHERE type = 'daily' AND target_type = 'earn_xp' AND is_active = true LIMIT 1;
    SELECT id INTO v_tpl_daily_use_comodin FROM gamification_system.mission_templates
        WHERE type = 'daily' AND target_type = 'use_comodines' AND is_active = true LIMIT 1;
    SELECT id INTO v_tpl_weekly_complete_module FROM gamification_system.mission_templates
        WHERE type = 'weekly' AND target_type = 'complete_modules' AND is_active = true LIMIT 1;
    SELECT id INTO v_tpl_weekly_daily_streak FROM gamification_system.mission_templates
        WHERE type = 'weekly' AND target_type = 'daily_streak' AND is_active = true LIMIT 1;
    SELECT id INTO v_tpl_weekly_perfect_scores FROM gamification_system.mission_templates
        WHERE type = 'weekly' AND target_type = 'perfect_scores' AND is_active = true LIMIT 1;
    SELECT id INTO v_tpl_weekly_explorer FROM gamification_system.mission_templates
        WHERE type = 'weekly' AND target_type = 'explore_modules' AND is_active = true LIMIT 1;
    SELECT id INTO v_tpl_weekly_master_learner FROM gamification_system.mission_templates
        WHERE type = 'weekly' AND target_type = 'complete_exercises' AND is_active = true LIMIT 1;

    -- Validate that all templates were found
    IF v_tpl_daily_exercises IS NULL OR v_tpl_daily_earn_xp IS NULL OR v_tpl_daily_use_comodin IS NULL
       OR v_tpl_weekly_complete_module IS NULL OR v_tpl_weekly_daily_streak IS NULL
       OR v_tpl_weekly_perfect_scores IS NULL OR v_tpl_weekly_explorer IS NULL
       OR v_tpl_weekly_master_learner IS NULL THEN
        RAISE WARNING '[REC-009] Missing mission_templates — seed templates first. Skipping mission init for user %', p_user_id;
        RETURN;
    END IF;

    -- =====================================================
    -- DAILY MISSIONS (3)
    -- =====================================================

    -- Daily Mission 1: Complete exercises
    INSERT INTO gamification_system.missions (
        user_id,
        template_id,
        title,
        description,
        mission_type,
        objectives,
        rewards,
        status,
        progress,
        start_date,
        end_date
    ) VALUES (
        p_user_id,
        v_tpl_daily_exercises,
        'Completar 3 ejercicios',
        'Completa 3 ejercicios hoy para ganar recompensas',
        'daily',
        jsonb_build_array(
            jsonb_build_object(
                'type', 'complete_exercises',
                'target', 3,
                'current', 0
            )
        ),
        jsonb_build_object(
            'xp', 50,
            'ml_coins', 25
        ),
        'active',
        0,
        v_today_start,
        v_today_end
    )
    ON CONFLICT DO NOTHING;

    -- Daily Mission 2: Earn XP
    INSERT INTO gamification_system.missions (
        user_id,
        template_id,
        title,
        description,
        mission_type,
        objectives,
        rewards,
        status,
        progress,
        start_date,
        end_date
    ) VALUES (
        p_user_id,
        v_tpl_daily_earn_xp,
        'Ganar 100 XP',
        'Acumula 100 puntos de experiencia hoy',
        'daily',
        jsonb_build_array(
            jsonb_build_object(
                'type', 'earn_xp',
                'target', 100,
                'current', 0
            )
        ),
        jsonb_build_object(
            'xp', 30,
            'ml_coins', 15
        ),
        'active',
        0,
        v_today_start,
        v_today_end
    )
    ON CONFLICT DO NOTHING;

    -- Daily Mission 3: Use comodín
    INSERT INTO gamification_system.missions (
        user_id,
        template_id,
        title,
        description,
        mission_type,
        objectives,
        rewards,
        status,
        progress,
        start_date,
        end_date
    ) VALUES (
        p_user_id,
        v_tpl_daily_use_comodin,
        'Usar un comodín',
        'Usa al menos un comodín en un ejercicio',
        'daily',
        jsonb_build_array(
            jsonb_build_object(
                'type', 'use_comodines',
                'target', 1,
                'current', 0
            )
        ),
        jsonb_build_object(
            'xp', 20,
            'ml_coins', 10
        ),
        'active',
        0,
        v_today_start,
        v_today_end
    )
    ON CONFLICT DO NOTHING;

    -- =====================================================
    -- WEEKLY MISSIONS (5)
    -- =====================================================

    -- Weekly Mission 1: Complete a module
    INSERT INTO gamification_system.missions (
        user_id,
        template_id,
        title,
        description,
        mission_type,
        objectives,
        rewards,
        status,
        progress,
        start_date,
        end_date
    ) VALUES (
        p_user_id,
        v_tpl_weekly_complete_module,
        'Completar un módulo',
        'Completa un módulo completo esta semana',
        'weekly',
        jsonb_build_array(
            jsonb_build_object(
                'type', 'complete_modules',
                'target', 1,
                'current', 0
            )
        ),
        jsonb_build_object(
            'xp', 200,
            'ml_coins', 100
        ),
        'active',
        0,
        v_today_start,
        v_week_end
    )
    ON CONFLICT DO NOTHING;

    -- Weekly Mission 2: Daily streak
    INSERT INTO gamification_system.missions (
        user_id,
        template_id,
        title,
        description,
        mission_type,
        objectives,
        rewards,
        status,
        progress,
        start_date,
        end_date
    ) VALUES (
        p_user_id,
        v_tpl_weekly_daily_streak,
        'Racha de 5 días',
        'Completa al menos un ejercicio durante 5 días seguidos',
        'weekly',
        jsonb_build_array(
            jsonb_build_object(
                'type', 'daily_streak',
                'target', 5,
                'current', 0
            )
        ),
        jsonb_build_object(
            'xp', 150,
            'ml_coins', 75
        ),
        'active',
        0,
        v_today_start,
        v_week_end
    )
    ON CONFLICT DO NOTHING;

    -- Weekly Mission 3: Perfect scores
    INSERT INTO gamification_system.missions (
        user_id,
        template_id,
        title,
        description,
        mission_type,
        objectives,
        rewards,
        status,
        progress,
        start_date,
        end_date
    ) VALUES (
        p_user_id,
        v_tpl_weekly_perfect_scores,
        'Perfección absoluta',
        'Obtén 3 puntajes perfectos (100%) en ejercicios',
        'weekly',
        jsonb_build_array(
            jsonb_build_object(
                'type', 'perfect_scores',
                'target', 3,
                'current', 0
            )
        ),
        jsonb_build_object(
            'xp', 180,
            'ml_coins', 90
        ),
        'active',
        0,
        v_today_start,
        v_week_end
    )
    ON CONFLICT DO NOTHING;

    -- Weekly Mission 4: Explorer
    INSERT INTO gamification_system.missions (
        user_id,
        template_id,
        title,
        description,
        mission_type,
        objectives,
        rewards,
        status,
        progress,
        start_date,
        end_date
    ) VALUES (
        p_user_id,
        v_tpl_weekly_explorer,
        'Explorador curioso',
        'Completa ejercicios de 3 módulos diferentes',
        'weekly',
        jsonb_build_array(
            jsonb_build_object(
                'type', 'explore_modules',
                'target', 3,
                'current', 0,
                'modules_visited', '[]'::jsonb
            )
        ),
        jsonb_build_object(
            'xp', 120,
            'ml_coins', 60
        ),
        'active',
        0,
        v_today_start,
        v_week_end
    )
    ON CONFLICT DO NOTHING;

    -- Weekly Mission 5: Master learner
    INSERT INTO gamification_system.missions (
        user_id,
        template_id,
        title,
        description,
        mission_type,
        objectives,
        rewards,
        status,
        progress,
        start_date,
        end_date
    ) VALUES (
        p_user_id,
        v_tpl_weekly_master_learner,
        'Maestro del aprendizaje',
        'Completa 15 ejercicios esta semana',
        'weekly',
        jsonb_build_array(
            jsonb_build_object(
                'type', 'complete_exercises',
                'target', 15,
                'current', 0
            )
        ),
        jsonb_build_object(
            'xp', 250,
            'ml_coins', 125
        ),
        'active',
        0,
        v_today_start,
        v_week_end
    )
    ON CONFLICT DO NOTHING;

EXCEPTION
    WHEN OTHERS THEN
        -- P1-001: Capturar error sin propagar, ya que initialize_user_stats maneja el error general
        GET STACKED DIAGNOSTICS
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_code = RETURNED_SQLSTATE;

        RAISE WARNING '[P1-001] Error inicializando misiones para usuario %: % (SQLSTATE: %)',
            p_user_id, v_error_message, v_error_code;

        -- Registrar en pending_user_initialization para retry posterior
        BEGIN
            INSERT INTO audit_logging.pending_user_initialization (
                user_id,
                profile_id,
                error_message,
                error_code,
                error_detail,
                trigger_name,
                function_name,
                status,
                next_retry_at
            ) VALUES (
                p_user_id,
                p_user_id,
                v_error_message,
                v_error_code,
                v_error_detail,
                'initialize_user_stats',
                'gamilit.initialize_user_missions',
                'pending',
                gamilit.now_mexico() + INTERVAL '5 minutes'
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[P1-001] No se pudo registrar error de misiones: %', SQLERRM;
        END;
        -- No re-lanzar excepción, el usuario aún puede usar la plataforma sin misiones
END;
$$;


