-- Name: cleanup_rate_limit_logs(integer); Type: FUNCTION; Schema: notifications; Owner: postgres
--

CREATE FUNCTION notifications.cleanup_rate_limit_logs(older_than_days integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM notifications.rate_limit_logs
    WHERE created_at < NOW() - (older_than_days || ' days')::INTERVAL;

    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;


