--
-- TOC entry 759 (class 1255 OID 145582)
-- Name: queue_batch_notifications(uuid[], character varying, character varying, text, jsonb, character varying); Type: FUNCTION; Schema: notifications; Owner: postgres
--

CREATE FUNCTION notifications.queue_batch_notifications(p_user_ids uuid[], p_type character varying, p_title character varying, p_message text, p_data jsonb DEFAULT '{}'::jsonb, p_priority character varying DEFAULT 'normal'::character varying) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_user_id UUID;
    v_count INTEGER := 0;
    v_notification_id UUID;
BEGIN
    -- Validar que hay usuarios
    IF array_length(p_user_ids, 1) IS NULL OR array_length(p_user_ids, 1) = 0 THEN
        RAISE EXCEPTION 'No users provided for batch notification';
    END IF;

    -- Iterar sobre cada usuario y crear notificación
    FOREACH v_user_id IN ARRAY p_user_ids
    LOOP
        -- Usar la función send_notification para crear y encolar
        BEGIN
            v_notification_id := notifications.send_notification(
                v_user_id,
                p_type,
                p_title,
                p_message,
                p_data,
                p_priority
            );

            IF v_notification_id IS NOT NULL THEN
                v_count := v_count + 1;
            END IF;

        EXCEPTION
            WHEN OTHERS THEN
                -- Log del error pero continuar con los demás usuarios
                RAISE WARNING 'Error creating notification for user %: %', v_user_id, SQLERRM;
        END;
    END LOOP;

    RETURN v_count;
END;
$$;


