-- Name: FUNCTION get_classroom_analytics(p_classroom_id uuid, p_date_from timestamp with time zone, p_date_to timestamp with time zone); Type: COMMENT; Schema: progress_tracking; Owner: postgres
--

COMMENT ON FUNCTION progress_tracking.get_classroom_analytics(p_classroom_id uuid, p_date_from timestamp with time zone, p_date_to timestamp with time zone) IS 'Obtiene estadísticas y analytics completos de un classroom';


--
-- TOC entry 550 (class 1255 OID 145554)
-- Name: get_classroom_detailed_analytics(uuid); Type: FUNCTION; Schema: progress_tracking; Owner: postgres
--

CREATE FUNCTION progress_tracking.get_classroom_detailed_analytics(p_classroom_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_result JSON;
BEGIN
    SELECT json_build_object(
        'classroom_id', p_classroom_id,
        'classroom_name', c.name,
        'student_count', (
            SELECT COUNT(*)
            FROM social_features.classroom_members
            WHERE classroom_id = p_classroom_id AND is_active = TRUE
        ),
        'active_students_week', (
            SELECT COUNT(DISTINCT cm.student_id)
            FROM social_features.classroom_members cm
            JOIN gamification_system.user_stats us ON us.user_id = cm.student_id
            WHERE cm.classroom_id = p_classroom_id
              AND cm.is_active = TRUE
              AND us.last_activity_at >= CURRENT_DATE - 7
        ),
        'total_xp', (
            SELECT COALESCE(SUM(us.total_xp), 0)::BIGINT
            FROM gamification_system.user_stats us
            JOIN social_features.classroom_members cm ON cm.student_id = us.user_id
            WHERE cm.classroom_id = p_classroom_id
              AND cm.is_active = TRUE
        ),
        'avg_xp_per_student', (
            SELECT COALESCE(AVG(us.total_xp), 0)::INTEGER
            FROM gamification_system.user_stats us
            JOIN social_features.classroom_members cm ON cm.student_id = us.user_id
            WHERE cm.classroom_id = p_classroom_id
              AND cm.is_active = TRUE
        ),
        'avg_level', (
            SELECT COALESCE(AVG(us.level), 1)::DECIMAL(4,1)
            FROM gamification_system.user_stats us
            JOIN social_features.classroom_members cm ON cm.student_id = us.user_id
            WHERE cm.classroom_id = p_classroom_id
              AND cm.is_active = TRUE
        ),
        'total_exercises_completed', (
            SELECT COALESCE(SUM(us.exercises_completed), 0)::INTEGER
            FROM gamification_system.user_stats us
            JOIN social_features.classroom_members cm ON cm.student_id = us.user_id
            WHERE cm.classroom_id = p_classroom_id
              AND cm.is_active = TRUE
        ),
        'avg_streak', (
            SELECT COALESCE(AVG(us.current_streak), 0)::DECIMAL(4,1)
            FROM gamification_system.user_stats us
            JOIN social_features.classroom_members cm ON cm.student_id = us.user_id
            WHERE cm.classroom_id = p_classroom_id
              AND cm.is_active = TRUE
        ),
        'assigned_modules', (
            SELECT COUNT(*)
            FROM educational_content.classroom_modules
            WHERE classroom_id = p_classroom_id AND is_active = TRUE
        ),
        'top_students', (
            SELECT json_agg(top_data)
            FROM (
                SELECT json_build_object(
                    'student_id', us.user_id,
                    'name', p.display_name,
                    'xp', us.total_xp,
                    'level', us.level,
                    'rank', us.current_rank::TEXT
                ) as top_data
                FROM gamification_system.user_stats us
                JOIN social_features.classroom_members cm ON cm.student_id = us.user_id
                JOIN auth_management.profiles p ON p.id = us.user_id
                WHERE cm.classroom_id = p_classroom_id
                  AND cm.is_active = TRUE
                ORDER BY us.total_xp DESC
                LIMIT 5
            ) top_5
        )
    ) INTO v_result
    FROM social_features.classrooms c
    WHERE c.id = p_classroom_id;

    RETURN v_result;
END;
$$;


