CREATE FUNCTION social_features.reject_friend_request(p_request_id uuid, p_recipient_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Actualizar solicitud a 'rejected'
    UPDATE social_features.friend_requests
    SET status = 'rejected',
        responded_at = gamilit.now_mexico()
    WHERE id = p_request_id
      AND recipient_id = p_recipient_id
      AND status = 'pending';

    RETURN FOUND;
END;
$$;


