-- TOC entry 518 (class 1255 OID 140425)
-- Name: get_gamification_param(character varying, uuid, uuid); Type: FUNCTION; Schema: system_configuration; Owner: postgres
--

CREATE FUNCTION system_configuration.get_gamification_param(p_param_key character varying, p_tenant_id uuid DEFAULT NULL::uuid, p_classroom_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_param RECORD;
    v_value JSONB;
BEGIN
    -- Get parameter
    SELECT * INTO v_param
    FROM system_configuration.gamification_parameters
    WHERE param_key = p_param_key
      AND is_active = TRUE;

    IF NOT FOUND THEN
        RETURN NULL;  -- Parameter doesn't exist
    END IF;

    -- Check classroom override (highest priority)
    IF p_classroom_id IS NOT NULL AND v_param.is_overridable THEN
        v_value := v_param.classroom_overrides->p_classroom_id::TEXT->'value';
        IF v_value IS NOT NULL THEN
            RETURN v_value;
        END IF;
    END IF;

    -- Check tenant override
    IF p_tenant_id IS NOT NULL AND v_param.is_overridable THEN
        v_value := v_param.tenant_overrides->p_tenant_id::TEXT;
        IF v_value IS NOT NULL THEN
            RETURN v_value;
        END IF;
    END IF;

    -- Return default parameter value
    RETURN v_param.param_value;
END;
$$;


