-- TOC entry 513 (class 1255 OID 140426)
-- Name: set_classroom_gamification_override(character varying, uuid, jsonb, text); Type: FUNCTION; Schema: system_configuration; Owner: postgres
--

CREATE FUNCTION system_configuration.set_classroom_gamification_override(p_param_key character varying, p_classroom_id uuid, p_value jsonb, p_reason text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_override JSONB;
BEGIN
    -- Build override object
    v_override := jsonb_build_object(
        'value', p_value,
        'reason', p_reason,
        'set_at', NOW()
    );

    -- Update parameter
    UPDATE system_configuration.gamification_parameters
    SET classroom_overrides = classroom_overrides || jsonb_build_object(p_classroom_id::TEXT, v_override),
        updated_at = NOW()
    WHERE param_key = p_param_key
      AND is_active = TRUE
      AND is_overridable = TRUE;

    RETURN FOUND;
END;
$$;


