--
-- TOC entry 479 (class 1259 OID 145596)
-- Name: classroom_overview; Type: VIEW; Schema: admin_dashboard; Owner: postgres
--

CREATE VIEW admin_dashboard.classroom_overview AS
 SELECT c.id AS classroom_id,
    c.name AS classroom_name,
    c.description AS classroom_description,
    t.id AS teacher_id,
    t.display_name AS teacher_name,
    count(DISTINCT u.id) AS total_students,
    count(DISTINCT
        CASE
            WHEN (u.status = 'active'::auth_management.user_status) THEN u.id
            ELSE NULL::uuid
        END) AS active_students,
    count(DISTINCT
        CASE
            WHEN (u.status = 'inactive'::auth_management.user_status) THEN u.id
            ELSE NULL::uuid
        END) AS inactive_students,
    count(DISTINCT a.id) AS total_assignments,
    count(DISTINCT
        CASE
            WHEN (a.due_date > now()) THEN a.id
            ELSE NULL::uuid
        END) AS pending_assignments,
    count(DISTINCT
        CASE
            WHEN ((a.due_date <= now()) AND (a.due_date > (now() - '7 days'::interval))) THEN a.id
            ELSE NULL::uuid
        END) AS upcoming_deadline_assignments,
    count(DISTINCT ex.id) AS total_exercises,
    round(avg(
        CASE
            WHEN (up.progress_percentage IS NOT NULL) THEN up.progress_percentage
            ELSE 0
        END), 2) AS avg_class_progress_percent,
    max(c.updated_at) AS last_updated,
    c.created_at AS classroom_created_at,
        CASE
            WHEN (count(DISTINCT u.id) = 0) THEN 'EMPTY'::text
            WHEN (count(DISTINCT
            CASE
                WHEN (u.status = 'active'::auth_management.user_status) THEN u.id
                ELSE NULL::uuid
            END) > 0) THEN 'ACTIVE'::text
            ELSE 'INACTIVE'::text
        END AS classroom_status
   FROM (((((((social_features.classrooms c
     LEFT JOIN auth_management.profiles t ON ((c.teacher_id = t.id)))
     LEFT JOIN social_features.classroom_members cm ON ((c.id = cm.classroom_id)))
     LEFT JOIN auth_management.profiles u ON ((cm.student_id = u.id)))
     LEFT JOIN social_features.assignment_classrooms ac ON ((c.id = ac.classroom_id)))
     LEFT JOIN educational_content.assignments a ON ((ac.assignment_id = a.id)))
     LEFT JOIN educational_content.exercises ex ON ((ex.module_id IN ( SELECT modules.id
           FROM educational_content.modules))))
     LEFT JOIN progress_tracking.module_progress up ON ((u.id = up.user_id)))
  WHERE (c.is_deleted = false)
  GROUP BY c.id, c.name, c.description, c.created_at, c.updated_at, t.id, t.display_name;


ALTER VIEW admin_dashboard.classroom_overview OWNER TO postgres;

--
-- TOC entry 9715 (class 0 OID 0)
-- Dependencies: 479
-- Name: VIEW classroom_overview; Type: COMMENT; Schema: admin_dashboard; Owner: postgres
--

COMMENT ON VIEW admin_dashboard.classroom_overview IS 'Provides a comprehensive overview of classroom statistics including student count, assignments, and progress.

CORRECTED (2025-11-24 - ISSUE-P2-001):
- Fixed JOIN with assignments table (M2M relationship through assignment_classrooms)
- Changed: assignments a ON a.classroom_id = c.id (column does not exist)
- To: assignment_classrooms ac ON c.id = ac.classroom_id, then assignments a ON ac.assignment_id = a.id

Columns:
  - classroom_id: Unique identifier of the classroom
  - classroom_name: Name of the classroom
  - classroom_description: Description of the classroom
  - teacher_id: ID of the teacher managing the classroom
  - teacher_name: Display name of the teacher
  - total_students: Total number of students enrolled
  - active_students: Number of currently active students
  - inactive_students: Number of inactive students
  - total_assignments: Total number of assignments in the classroom
  - pending_assignments: Number of assignments with future due dates
  - upcoming_deadline_assignments: Assignments due in the next 7 days
  - total_exercises: Total number of exercises
  - avg_class_progress_percent: Average progress of the classroom
  - last_updated: Most recent update timestamp
  - classroom_created_at: When the classroom was created
  - classroom_status: Current status (EMPTY, ACTIVE, INACTIVE)
Usage:
  SELECT * FROM classroom_overview WHERE classroom_status = ''ACTIVE'';
  SELECT classroom_name, total_students, avg_class_progress_percent
  FROM classroom_overview
  ORDER BY avg_class_progress_percent DESC;
  SELECT * FROM classroom_overview WHERE pending_assignments > 0;';


