--
-- TOC entry 480 (class 1259 OID 145601)
-- Name: moderation_queue; Type: VIEW; Schema: admin_dashboard; Owner: postgres
--

CREATE VIEW admin_dashboard.moderation_queue AS
 SELECT fc.id,
    fc.content_type,
    fc.content_id,
    fc.content_preview,
    fc.reason,
    fc.priority,
    fc.status,
    fc.created_at,
    p.email AS reporter_email,
    COALESCE(p.full_name, p.display_name, p.email) AS reporter_name
   FROM (content_management.flagged_contents fc
     LEFT JOIN auth_management.profiles p ON ((fc.reported_by = p.id)))
  WHERE ((fc.status)::text = 'pending'::text)
  ORDER BY
        CASE fc.priority
            WHEN 'high'::text THEN 1
            WHEN 'medium'::text THEN 2
            WHEN 'low'::text THEN 3
            ELSE NULL::integer
        END, fc.created_at;


