--
-- TOC entry 499 (class 1259 OID 145759)
-- Name: user_analytics_mv; Type: MATERIALIZED VIEW; Schema: admin_dashboard; Owner: gamilit_user
--

CREATE MATERIALIZED VIEW admin_dashboard.user_analytics_mv AS
 SELECT p.id AS user_id,
    p.display_name,
    p.email,
    p.avatar_url,
    ur.role,
    p.tenant_id,
    p.status,
    p.created_at AS registered_at,
    COALESCE(us.total_xp, 0) AS total_xp,
    COALESCE(us.level, 1) AS current_level,
    COALESCE((us.current_rank)::text, 'ajaw'::text) AS current_rank,
    COALESCE(us.ml_coins, 0) AS ml_coins,
    COALESCE(us.ml_coins_earned_total, 0) AS ml_coins_earned,
    COALESCE(us.exercises_completed, 0) AS exercises_completed,
    COALESCE(us.modules_completed, 0) AS missions_completed,
    COALESCE(us.current_streak, 0) AS current_streak,
    COALESCE(us.max_streak, 0) AS longest_streak,
    us.last_activity_at,
    LEAST(100, ((((COALESCE(us.exercises_completed, 0) * 2) + (COALESCE(us.modules_completed, 0) * 10)) + (COALESCE(us.current_streak, 0) * 5)) / 10)) AS engagement_score,
    ( SELECT count(*) AS count
           FROM social_features.classroom_members cm
          WHERE ((cm.student_id = p.id) AND (cm.is_active = true))) AS enrolled_classrooms_count,
    ( SELECT count(*) AS count
           FROM social_features.teacher_classrooms tc
          WHERE (tc.teacher_id = p.id)) AS teaching_classrooms_count,
    ( SELECT user_sessions.last_activity_at
           FROM auth_management.user_sessions
          WHERE (user_sessions.user_id = p.id)
          ORDER BY user_sessions.last_activity_at DESC
         LIMIT 1) AS last_session_at,
    now() AS snapshot_timestamp
   FROM ((auth_management.profiles p
     LEFT JOIN auth_management.user_roles ur ON (((ur.user_id = p.id) AND (ur.is_active = true))))
     LEFT JOIN gamification_system.user_stats us ON ((us.user_id = p.id)))
  WHERE (p.status = 'active'::auth_management.user_status)
  WITH NO DATA;


ALTER MATERIALIZED VIEW admin_dashboard.user_analytics_mv OWNER TO gamilit_user;

--
-- TOC entry 9875 (class 0 OID 0)
-- Dependencies: 499
-- Name: MATERIALIZED VIEW user_analytics_mv; Type: COMMENT; Schema: admin_dashboard; Owner: gamilit_user
--

COMMENT ON MATERIALIZED VIEW admin_dashboard.user_analytics_mv IS 'Per-user analytics including gamification stats, engagement metrics, and activity tracking.
Refresh with: REFRESH MATERIALIZED VIEW CONCURRENTLY admin_dashboard.user_analytics_mv;';


--
-- TOC entry 483 (class 1259 OID 145615)
-- Name: user_stats_summary; Type: VIEW; Schema: admin_dashboard; Owner: postgres
--

CREATE VIEW admin_dashboard.user_stats_summary AS
 SELECT count(*) FILTER (WHERE (deleted_at IS NULL)) AS total_users,
    count(*) FILTER (WHERE (created_at >= CURRENT_DATE)) AS users_today,
    count(*) FILTER (WHERE (created_at >= (CURRENT_DATE - '7 days'::interval))) AS users_this_week,
    count(*) FILTER (WHERE (created_at >= (CURRENT_DATE - '30 days'::interval))) AS users_this_month,
    count(*) FILTER (WHERE (last_sign_in_at >= CURRENT_DATE)) AS active_users_today,
    count(*) FILTER (WHERE (last_sign_in_at >= (CURRENT_DATE - '7 days'::interval))) AS active_users_week,
    count(*) FILTER (WHERE ((role)::text = 'student'::text)) AS total_students,
    count(*) FILTER (WHERE ((role)::text = 'admin_teacher'::text)) AS total_teachers,
    count(*) FILTER (WHERE ((role)::text = 'super_admin'::text)) AS total_admins
   FROM auth.users;


