--
-- TOC entry 491 (class 1259 OID 145653)
-- Name: v_student_engagement_metrics; Type: VIEW; Schema: data_warehouse; Owner: gamilit_user
--

CREATE VIEW data_warehouse.v_student_engagement_metrics AS
 WITH recent_progress AS (
         SELECT fdp.student_key,
            fdp.date_key,
            dd.full_date,
            dd.day_of_week,
            dd.is_weekend,
            fdp.login_count,
            fdp.sessions_count,
            fdp.total_time_spent_seconds,
            fdp.streak_days,
            fdp.is_active_day,
            fdp.exercises_completed,
            fdp.xp_earned,
            fdp.ml_coins_earned
           FROM (data_warehouse.fact_daily_progress fdp
             JOIN data_warehouse.dim_dates dd ON ((fdp.date_key = dd.date_key)))
          WHERE (dd.full_date >= (CURRENT_DATE - '90 days'::interval))
        ), daily_aggregates AS (
         SELECT rp.student_key,
            sum(
                CASE
                    WHEN (rp.full_date >= (CURRENT_DATE - '7 days'::interval)) THEN rp.login_count
                    ELSE 0
                END) AS login_count_7d,
            sum(
                CASE
                    WHEN (rp.full_date >= (CURRENT_DATE - '30 days'::interval)) THEN rp.login_count
                    ELSE 0
                END) AS login_count_30d,
            sum(rp.login_count) AS login_count_90d,
            sum(rp.sessions_count) AS total_sessions_90d,
            avg(
                CASE
                    WHEN (rp.sessions_count > 0) THEN ((rp.total_time_spent_seconds)::double precision / (rp.sessions_count)::double precision)
                    ELSE NULL::double precision
                END) AS avg_session_duration_seconds,
            sum(rp.total_time_spent_seconds) AS total_time_spent_90d,
            max(rp.streak_days) AS max_streak_90d,
            count(*) FILTER (WHERE (rp.is_active_day = true)) AS active_days_90d,
            count(DISTINCT rp.full_date) FILTER (WHERE ((rp.is_active_day = true) AND (rp.full_date >= (CURRENT_DATE - '7 days'::interval)))) AS active_days_7d,
            count(DISTINCT rp.full_date) FILTER (WHERE ((rp.is_active_day = true) AND (rp.full_date >= (CURRENT_DATE - '30 days'::interval)))) AS active_days_30d,
            sum(rp.exercises_completed) AS exercises_completed_90d,
            ((sum(
                CASE
                    WHEN rp.is_weekend THEN rp.login_count
                    ELSE 0
                END))::double precision / (NULLIF(sum(rp.login_count), 0))::double precision) AS weekend_activity_ratio,
            mode() WITHIN GROUP (ORDER BY rp.day_of_week) FILTER (WHERE (rp.is_active_day = true)) AS most_active_day_of_week,
                CASE
                    WHEN (avg(rp.login_count) > (0)::numeric) THEN (stddev(rp.login_count) / avg(rp.login_count))
                    ELSE (1)::numeric
                END AS activity_variation_coefficient,
            sum(rp.xp_earned) AS xp_earned_90d,
            sum(rp.ml_coins_earned) AS ml_coins_earned_90d
           FROM recent_progress rp
          GROUP BY rp.student_key
        ), last_activity AS (
         SELECT recent_progress.student_key,
            max(recent_progress.full_date) AS last_activity_date,
            (CURRENT_DATE - max(recent_progress.full_date)) AS days_since_last_login
           FROM recent_progress
          WHERE (recent_progress.is_active_day = true)
          GROUP BY recent_progress.student_key
        ), current_streak AS (
         SELECT ranked.student_key,
            ranked.streak_days AS current_streak
           FROM ( SELECT rp.student_key,
                    rp.streak_days,
                    row_number() OVER (PARTITION BY rp.student_key ORDER BY rp.full_date DESC) AS rn
                   FROM recent_progress rp
                  WHERE (rp.is_active_day = true)) ranked
          WHERE (ranked.rn = 1)
        )
 SELECT ds.student_key,
    ds.student_id,
    ds.display_name,
    ds.email,
    ds.current_rank,
    ds.current_level,
    COALESCE(da.login_count_7d, (0)::bigint) AS login_count_7d,
    COALESCE(da.login_count_30d, (0)::bigint) AS login_count_30d,
    COALESCE(da.login_count_90d, (0)::bigint) AS login_count_90d,
    COALESCE(da.total_sessions_90d, (0)::bigint) AS total_sessions_90d,
    COALESCE((da.avg_session_duration_seconds / (60)::double precision), (0)::double precision) AS avg_session_duration_minutes,
    COALESCE((da.total_time_spent_90d / 60), (0)::bigint) AS total_time_spent_minutes_90d,
    COALESCE(cs.current_streak, 0) AS current_streak,
    COALESCE(da.max_streak_90d, 0) AS max_streak_90d,
    COALESCE(da.active_days_7d, (0)::bigint) AS active_days_7d,
    COALESCE(da.active_days_30d, (0)::bigint) AS active_days_30d,
    COALESCE(da.active_days_90d, (0)::bigint) AS active_days_90d,
    COALESCE(la.days_since_last_login, 90) AS days_since_last_login,
    COALESCE(da.exercises_completed_90d, (0)::bigint) AS exercises_completed_90d,
    COALESCE(da.weekend_activity_ratio, (0)::double precision) AS weekend_activity_ratio,
    COALESCE(da.most_active_day_of_week, 3) AS most_active_day_of_week,
    COALESCE(((1)::numeric - da.activity_variation_coefficient), 0.5) AS activity_regularity_score,
    COALESCE(da.xp_earned_90d, (0)::bigint) AS xp_earned_90d,
    COALESCE(da.ml_coins_earned_90d, (0)::bigint) AS ml_coins_earned_90d,
        CASE
            WHEN (da.login_count_7d > 0) THEN true
            ELSE false
        END AS is_active_last_7d,
        CASE
            WHEN (da.active_days_30d > 0) THEN ((da.exercises_completed_90d)::double precision / (da.active_days_90d)::double precision)
            ELSE (0)::double precision
        END AS exercises_per_active_day,
    la.last_activity_date,
    CURRENT_TIMESTAMP AS generated_at
   FROM (((data_warehouse.dim_students ds
     LEFT JOIN daily_aggregates da ON ((ds.student_key = da.student_key)))
     LEFT JOIN last_activity la ON ((ds.student_key = la.student_key)))
     LEFT JOIN current_streak cs ON ((ds.student_key = cs.student_key)))
  WHERE ((ds.is_current = true) AND (ds.role = 'student'::text));


ALTER VIEW data_warehouse.v_student_engagement_metrics OWNER TO gamilit_user;

