Sprint 3.1 - Feature Engineering for ML Predictions';


--
-- TOC entry 492 (class 1259 OID 145658)
-- Name: v_student_performance_metrics; Type: VIEW; Schema: data_warehouse; Owner: gamilit_user
--

CREATE VIEW data_warehouse.v_student_performance_metrics AS
 WITH recent_completions AS (
         SELECT fec.student_key,
            fec.date_key,
            fec.exercise_key,
            fec.module_key,
            dd_1.full_date,
            fec.score_percentage,
            fec.time_spent_seconds,
            fec.is_passed,
            fec.is_perfect,
            fec.is_first_attempt,
            fec.hints_used,
            fec.attempt_number,
            de.difficulty_level,
            dm.module_id,
            dm.module_code
           FROM (((data_warehouse.fact_exercise_completions fec
             JOIN data_warehouse.dim_dates dd_1 ON ((fec.date_key = dd_1.date_key)))
             JOIN data_warehouse.dim_exercises de ON ((fec.exercise_key = de.exercise_key)))
             JOIN data_warehouse.dim_modules dm ON ((fec.module_key = dm.module_key)))
          WHERE (dd_1.full_date >= (CURRENT_DATE - '90 days'::interval))
        ), score_aggregates AS (
         SELECT rc.student_key,
            avg(
                CASE
                    WHEN (rc.full_date >= (CURRENT_DATE - '7 days'::interval)) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS avg_score_7d,
            avg(
                CASE
                    WHEN (rc.full_date >= (CURRENT_DATE - '30 days'::interval)) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS avg_score_30d,
            avg(rc.score_percentage) AS avg_score_90d,
            min(rc.score_percentage) AS min_score_90d,
            max(rc.score_percentage) AS max_score_90d,
            variance(rc.score_percentage) AS score_variance,
            stddev(rc.score_percentage) AS score_stddev,
            count(*) FILTER (WHERE rc.is_perfect) AS perfect_score_count_90d,
            avg(rc.time_spent_seconds) AS avg_time_per_exercise_seconds,
            min(rc.time_spent_seconds) AS min_time_per_exercise_seconds,
            max(rc.time_spent_seconds) AS max_time_per_exercise_seconds
           FROM recent_completions rc
          GROUP BY rc.student_key
        ), completion_rates AS (
         SELECT rc.student_key,
            count(*) FILTER (WHERE rc.is_passed) AS exercises_completed_90d,
            count(*) AS exercises_attempted_90d,
            count(*) FILTER (WHERE (NOT rc.is_passed)) AS exercises_failed_90d,
            (((count(*) FILTER (WHERE (rc.is_passed AND (rc.full_date >= (CURRENT_DATE - '7 days'::interval)))))::double precision / (NULLIF(count(*) FILTER (WHERE (rc.full_date >= (CURRENT_DATE - '7 days'::interval))), 0))::double precision) * (100)::double precision) AS completion_rate_7d,
            (((count(*) FILTER (WHERE (rc.is_passed AND (rc.full_date >= (CURRENT_DATE - '30 days'::interval)))))::double precision / (NULLIF(count(*) FILTER (WHERE (rc.full_date >= (CURRENT_DATE - '30 days'::interval))), 0))::double precision) * (100)::double precision) AS completion_rate_30d,
            (((count(*) FILTER (WHERE rc.is_passed))::double precision / (NULLIF(count(*), 0))::double precision) * (100)::double precision) AS completion_rate_90d,
            (((count(*) FILTER (WHERE (rc.is_first_attempt AND rc.is_passed)))::double precision / (NULLIF(count(*) FILTER (WHERE rc.is_first_attempt), 0))::double precision) * (100)::double precision) AS first_attempt_success_rate,
            ((count(*) FILTER (WHERE (rc.hints_used > 0)))::double precision / (NULLIF(count(*), 0))::double precision) AS hints_usage_rate,
            avg(rc.hints_used) AS avg_hints_per_exercise,
            avg(rc.attempt_number) AS avg_attempts_per_exercise
           FROM recent_completions rc
          GROUP BY rc.student_key
        ), difficulty_distribution AS (
         SELECT rc.student_key,
            ((count(*) FILTER (WHERE (rc.difficulty_level = 'easy'::text)))::double precision / (NULLIF(count(*), 0))::double precision) AS difficulty_easy_ratio,
            ((count(*) FILTER (WHERE (rc.difficulty_level = 'medium'::text)))::double precision / (NULLIF(count(*), 0))::double precision) AS difficulty_medium_ratio,
            ((count(*) FILTER (WHERE (rc.difficulty_level = 'hard'::text)))::double precision / (NULLIF(count(*), 0))::double precision) AS difficulty_hard_ratio,
            avg(
                CASE
                    WHEN (rc.difficulty_level = 'easy'::text) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS avg_score_easy,
            avg(
                CASE
                    WHEN (rc.difficulty_level = 'medium'::text) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS avg_score_medium,
            avg(
                CASE
                    WHEN (rc.difficulty_level = 'hard'::text) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS avg_score_hard
           FROM recent_completions rc
          GROUP BY rc.student_key
        ), module_progress AS (
         SELECT rc.student_key,
            max(
                CASE
                    WHEN (rc.module_code = 'M1'::text) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS module_1_best_score,
            max(
                CASE
                    WHEN (rc.module_code = 'M2'::text) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS module_2_best_score,
            max(
                CASE
                    WHEN (rc.module_code = 'M3'::text) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS module_3_best_score,
            max(
                CASE
                    WHEN (rc.module_code = 'M4'::text) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS module_4_best_score,
            max(
                CASE
                    WHEN (rc.module_code = 'M5'::text) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS module_5_best_score,
            count(DISTINCT rc.module_key) AS modules_attempted
           FROM recent_completions rc
          GROUP BY rc.student_key
        ), improvement_trend AS (
         SELECT weekly_scores.student_key,
            regr_slope((weekly_scores.avg_score)::double precision, (weekly_scores.week_num)::double precision) AS improvement_slope
           FROM ( SELECT rc.student_key,
                    date_trunc('week'::text, (rc.full_date)::timestamp with time zone) AS week_start,
                    (EXTRACT(week FROM rc.full_date) - EXTRACT(week FROM (CURRENT_DATE - '90 days'::interval))) AS week_num,
                    avg(rc.score_percentage) AS avg_score
                   FROM recent_completions rc
                  GROUP BY rc.student_key, (date_trunc('week'::text, (rc.full_date)::timestamp with time zone)), (EXTRACT(week FROM rc.full_date))) weekly_scores
          GROUP BY weekly_scores.student_key
        )
 SELECT ds.student_key,
    ds.student_id,
    ds.display_name,
    ds.current_rank,
    ds.current_level,
    ds.total_xp,
    COALESCE(sa.avg_score_7d, (0)::numeric) AS avg_score_7d,
    COALESCE(sa.avg_score_30d, (0)::numeric) AS avg_score_30d,
    COALESCE(sa.avg_score_90d, (0)::numeric) AS avg_score_90d,
    COALESCE(sa.min_score_90d, (0)::numeric) AS min_score_90d,
    COALESCE(sa.max_score_90d, (0)::numeric) AS max_score_90d,
    COALESCE(sa.score_variance, (0)::numeric) AS score_variance,
    COALESCE(sa.score_stddev, (0)::numeric) AS score_stddev,
    COALESCE(sa.perfect_score_count_90d, (0)::bigint) AS perfect_score_count,
    COALESCE(sa.avg_time_per_exercise_seconds, (0)::numeric) AS avg_time_per_exercise_seconds,
    COALESCE(cr.exercises_completed_90d, (0)::bigint) AS exercises_completed_total,
    COALESCE(cr.exercises_attempted_90d, (0)::bigint) AS exercises_attempted_total,
    COALESCE(cr.exercises_failed_90d, (0)::bigint) AS exercises_failed_total,
    COALESCE(cr.completion_rate_7d, (0)::double precision) AS completion_rate_7d,
    COALESCE(cr.completion_rate_30d, (0)::double precision) AS completion_rate_30d,
    COALESCE(cr.completion_rate_90d, (0)::double precision) AS completion_rate_90d,
    COALESCE(cr.first_attempt_success_rate, (0)::double precision) AS first_attempt_success_rate,
    COALESCE(cr.hints_usage_rate, (0)::double precision) AS hints_usage_rate,
    COALESCE(cr.avg_hints_per_exercise, (0)::numeric) AS avg_hints_per_exercise,
    COALESCE(cr.avg_attempts_per_exercise, (1)::numeric) AS avg_attempts_per_exercise,
    COALESCE(dd.difficulty_easy_ratio, (0.33)::double precision) AS difficulty_easy_ratio,
    COALESCE(dd.difficulty_medium_ratio, (0.33)::double precision) AS difficulty_medium_ratio,
    COALESCE(dd.difficulty_hard_ratio, (0.33)::double precision) AS difficulty_hard_ratio,
    COALESCE(dd.avg_score_easy, (0)::numeric) AS avg_score_easy,
    COALESCE(dd.avg_score_medium, (0)::numeric) AS avg_score_medium,
    COALESCE(dd.avg_score_hard, (0)::numeric) AS avg_score_hard,
    COALESCE(mp.module_1_best_score, (0)::numeric) AS module_1_progress,
    COALESCE(mp.module_2_best_score, (0)::numeric) AS module_2_progress,
    COALESCE(mp.module_3_best_score, (0)::numeric) AS module_3_progress,
    COALESCE(mp.module_4_best_score, (0)::numeric) AS module_4_progress,
    COALESCE(mp.module_5_best_score, (0)::numeric) AS module_5_progress,
    COALESCE(mp.modules_attempted, (0)::bigint) AS modules_attempted,
    COALESCE(it.improvement_slope, (0)::double precision) AS improvement_trend,
        CASE
            WHEN (COALESCE(sa.score_variance, (0)::numeric) < (100)::numeric) THEN 'consistent'::text
            WHEN (COALESCE(sa.score_variance, (0)::numeric) < (300)::numeric) THEN 'moderate'::text
            ELSE 'variable'::text
        END AS score_consistency_category,
        CASE
            WHEN (COALESCE(it.improvement_slope, (0)::double precision) > (1)::double precision) THEN 'improving'::text
            WHEN (COALESCE(it.improvement_slope, (0)::double precision) < ('-1'::integer)::double precision) THEN 'declining'::text
            ELSE 'stable'::text
        END AS performance_trend_category,
    CURRENT_TIMESTAMP AS generated_at
   FROM (((((data_warehouse.dim_students ds
     LEFT JOIN score_aggregates sa ON ((ds.student_key = sa.student_key)))
     LEFT JOIN completion_rates cr ON ((ds.student_key = cr.student_key)))
     LEFT JOIN difficulty_distribution dd ON ((ds.student_key = dd.student_key)))
     LEFT JOIN module_progress mp ON ((ds.student_key = mp.student_key)))
     LEFT JOIN improvement_trend it ON ((ds.student_key = it.student_key)))
  WHERE ((ds.is_current = true) AND (ds.role = 'student'::text));


