--
-- TOC entry 493 (class 1259 OID 145664)
-- Name: v_student_feature_base; Type: VIEW; Schema: data_warehouse; Owner: gamilit_user
--

CREATE VIEW data_warehouse.v_student_feature_base AS
 SELECT ds.student_key,
    ds.student_id,
    ds.display_name,
    ds.email,
    ds.current_rank,
    ds.current_level,
    ds.total_xp,
    ds.ml_coins_balance,
    ds.grade_level,
    ds.school_id,
    ds.school_name,
    ds.status,
    ds.registration_date,
    ds.first_activity_date,
    ds.last_activity_date,
    (CURRENT_DATE - ds.registration_date) AS days_since_registration,
    (CURRENT_DATE - COALESCE(ds.first_activity_date, ds.registration_date)) AS days_since_first_activity,
        CASE ds.current_rank
            WHEN 'Alumno'::text THEN 1
            WHEN 'Aprendiz'::text THEN 2
            WHEN 'Estudiante'::text THEN 3
            WHEN 'Erudito'::text THEN 4
            WHEN 'Explorador'::text THEN 5
            WHEN 'Investigador'::text THEN 6
            WHEN 'Artesano'::text THEN 7
            WHEN 'Creador'::text THEN 8
            WHEN 'Innovador'::text THEN 9
            WHEN 'Experto'::text THEN 10
            WHEN 'Maestro'::text THEN 11
            WHEN 'Sabio'::text THEN 12
            WHEN 'Guardian'::text THEN 13
            ELSE 1
        END AS current_rank_level,
        CASE
            WHEN ((ds.display_name IS NOT NULL) AND (ds.school_id IS NOT NULL)) THEN 100
            WHEN (ds.display_name IS NOT NULL) THEN 60
            ELSE 20
        END AS profile_completeness,
    (ds.school_id IS NOT NULL) AS has_school_association,
    COALESCE(em.login_count_7d, (0)::bigint) AS login_frequency_7d,
    COALESCE(em.login_count_30d, (0)::bigint) AS login_frequency_30d,
    COALESCE(em.login_count_90d, (0)::bigint) AS login_frequency_90d,
    COALESCE(em.avg_session_duration_minutes, (0)::double precision) AS avg_session_duration,
    COALESCE(em.total_time_spent_minutes_90d, (0)::bigint) AS total_session_time_30d,
    COALESCE(em.current_streak, 0) AS streak_current,
    COALESCE(em.max_streak_90d, 0) AS streak_max,
    COALESCE(em.days_since_last_login, 90) AS days_since_last_login,
    COALESCE(em.weekend_activity_ratio, (0)::double precision) AS weekend_activity_ratio,
    COALESCE(em.total_sessions_90d, (0)::bigint) AS sessions_count_30d,
    COALESCE(em.exercises_per_active_day, (0)::double precision) AS avg_activities_per_session,
    COALESCE(em.is_active_last_7d, false) AS is_active_last_7d,
    COALESCE(em.activity_regularity_score, 0.5) AS activity_regularity_score,
    (em.activity_regularity_score > 0.5) AS has_consistent_schedule,
        CASE em.most_active_day_of_week
            WHEN 0 THEN 'Sunday'::text
            WHEN 1 THEN 'Monday'::text
            WHEN 2 THEN 'Tuesday'::text
            WHEN 3 THEN 'Wednesday'::text
            WHEN 4 THEN 'Thursday'::text
            WHEN 5 THEN 'Friday'::text
            WHEN 6 THEN 'Saturday'::text
            ELSE 'Unknown'::text
        END AS most_active_day_name,
    COALESCE(pm.avg_score_7d, (0)::numeric) AS avg_score_7d,
    COALESCE(pm.avg_score_30d, (0)::numeric) AS avg_score_30d,
    COALESCE(pm.avg_score_90d, (0)::numeric) AS avg_score_all,
    COALESCE(pm.completion_rate_7d, (0)::double precision) AS completion_rate_7d,
    COALESCE(pm.completion_rate_30d, (0)::double precision) AS completion_rate_30d,
    COALESCE(pm.exercises_completed_total, (0)::bigint) AS exercises_completed_total,
    COALESCE(pm.exercises_attempted_total, (0)::bigint) AS exercises_attempted_total,
    COALESCE(pm.exercises_failed_total, (0)::bigint) AS exercises_failed_total,
    COALESCE(pm.avg_time_per_exercise_seconds, (0)::numeric) AS avg_time_per_exercise,
    COALESCE(pm.perfect_score_count, (0)::bigint) AS perfect_score_count,
    COALESCE(pm.difficulty_easy_ratio, (0.33)::double precision) AS difficulty_easy_ratio,
    COALESCE(pm.difficulty_medium_ratio, (0.33)::double precision) AS difficulty_medium_ratio,
    COALESCE(pm.difficulty_hard_ratio, (0.33)::double precision) AS difficulty_hard_ratio,
    COALESCE(pm.score_variance, (0)::numeric) AS score_variance,
    COALESCE(pm.improvement_trend, (0)::double precision) AS improvement_trend,
    COALESCE(pm.hints_usage_rate, (0)::double precision) AS hints_usage_rate,
    COALESCE(pm.first_attempt_success_rate, (0)::double precision) AS first_attempt_success_rate,
    COALESCE(pm.module_1_progress, (0)::numeric) AS module_progress_m1,
    COALESCE(pm.module_2_progress, (0)::numeric) AS module_progress_m2,
    COALESCE(pm.module_3_progress, (0)::numeric) AS module_progress_m3,
    COALESCE(pm.module_4_progress, (0)::numeric) AS module_progress_m4,
    COALESCE(pm.module_5_progress, (0)::numeric) AS module_progress_m5,
        CASE
            WHEN (COALESCE(em.days_since_last_login, 90) > 14) THEN true
            WHEN (COALESCE(em.login_count_30d, (0)::bigint) < 3) THEN true
            WHEN ((COALESCE(pm.avg_score_30d, (0)::numeric) < (40)::numeric) AND (COALESCE(pm.exercises_attempted_total, (0)::bigint) > 10)) THEN true
            ELSE false
        END AS high_dropout_risk_indicator,
        CASE
            WHEN ((COALESCE(em.login_count_7d, (0)::bigint) >= 5) AND (COALESCE(em.current_streak, 0) >= 3)) THEN 'very_high'::text
            WHEN (COALESCE(em.login_count_7d, (0)::bigint) >= 3) THEN 'high'::text
            WHEN (COALESCE(em.login_count_30d, (0)::bigint) >= 5) THEN 'moderate'::text
            WHEN (COALESCE(em.login_count_30d, (0)::bigint) >= 1) THEN 'low'::text
            ELSE 'disengaged'::text
        END AS engagement_level,
        CASE
            WHEN (COALESCE(pm.avg_score_30d, (0)::numeric) >= (80)::numeric) THEN 'excellent'::text
            WHEN (COALESCE(pm.avg_score_30d, (0)::numeric) >= (60)::numeric) THEN 'good'::text
            WHEN (COALESCE(pm.avg_score_30d, (0)::numeric) >= (40)::numeric) THEN 'needs_improvement'::text
            ELSE 'at_risk'::text
        END AS performance_level,
    CURRENT_TIMESTAMP AS generated_at,
    '1.0.0'::text AS feature_version
   FROM ((data_warehouse.dim_students ds
     LEFT JOIN data_warehouse.v_student_engagement_metrics em ON ((ds.student_key = em.student_key)))
     LEFT JOIN data_warehouse.v_student_performance_metrics pm ON ((ds.student_key = pm.student_key)))
  WHERE ((ds.is_current = true) AND (ds.role = 'student'::text));


