CREATE TABLE educational_content.exercise_validation_audits (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    exercise_id uuid NOT NULL,
    user_id uuid NOT NULL,
    attempt_number integer NOT NULL,
    submitted_answer jsonb NOT NULL,
    submitted_at timestamp with time zone DEFAULT gamilit.now_mexico() NOT NULL,
    exercise_snapshot jsonb NOT NULL,
    validation_config_snapshot jsonb NOT NULL,
    is_correct boolean NOT NULL,
    score integer NOT NULL,
    max_score integer NOT NULL,
    feedback text,
    validation_details jsonb,
    validation_function_used text NOT NULL,
    validation_timestamp timestamp with time zone DEFAULT gamilit.now_mexico() NOT NULL,
