    recalculated_by uuid,
    recalculation_reason text,
    original_audit_id uuid,
    has_discrepancy boolean DEFAULT false,
    discrepancy_type text,
    discrepancy_notes text,
    client_metadata jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT gamilit.now_mexico(),
    updated_at timestamp with time zone DEFAULT gamilit.now_mexico(),
    CONSTRAINT chk_validation_audit_attempt_positive CHECK ((attempt_number > 0)),
    CONSTRAINT chk_validation_audit_discrepancy_type CHECK (((has_discrepancy = false) OR ((has_discrepancy = true) AND (discrepancy_type IS NOT NULL)))),
    CONSTRAINT chk_validation_audit_recalculation_data CHECK (((is_recalculated = false) OR ((is_recalculated = true) AND (recalculated_at IS NOT NULL) AND (recalculation_reason IS NOT NULL)))),
    CONSTRAINT chk_validation_audit_score_range CHECK (((score >= 0) AND (score <= max_score)))
);


