--
-- TOC entry 488 (class 1259 OID 145638)
-- Name: v_validation_analysis; Type: VIEW; Schema: educational_content; Owner: postgres
--

CREATE VIEW educational_content.v_validation_analysis AS
 SELECT va.id AS audit_id,
    va.exercise_id,
    e.title AS exercise_title,
    e.exercise_type,
    e.module_id,
    m.title AS module_title,
    va.user_id,
    va.attempt_number,
    va.validation_function_used,
    va.is_correct,
    va.score,
    va.max_score,
    round((((va.score)::numeric / (NULLIF(va.max_score, 0))::numeric) * (100)::numeric), 2) AS score_percentage,
    va.feedback,
    va.validation_timestamp,
    va.validation_duration_ms,
    va.is_recalculated,
    va.recalculated_at,
    va.recalculated_by,
    va.recalculation_reason,
    va.original_audit_id,
    va.has_discrepancy,
    va.discrepancy_type,
    va.discrepancy_notes,
        CASE
            WHEN va.is_recalculated THEN ( SELECT exercise_validation_audits.score
               FROM educational_content.exercise_validation_audits
              WHERE (exercise_validation_audits.id = va.original_audit_id))
            ELSE NULL::integer
        END AS original_score,
        CASE
            WHEN va.is_recalculated THEN (va.score - ( SELECT exercise_validation_audits.score
               FROM educational_content.exercise_validation_audits
              WHERE (exercise_validation_audits.id = va.original_audit_id)))
            ELSE NULL::integer
        END AS score_difference,
    va.submitted_at,
    va.client_metadata,
    va.created_at,
    va.updated_at
   FROM ((educational_content.exercise_validation_audits va
     JOIN educational_content.exercises e ON ((e.id = va.exercise_id)))
     LEFT JOIN educational_content.modules m ON ((m.id = e.module_id)));


ALTER VIEW educational_content.v_validation_analysis OWNER TO postgres;

--
-- TOC entry 10312 (class 0 OID 0)
-- Dependencies: 488
-- Name: VIEW v_validation_analysis; Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON VIEW educational_content.v_validation_analysis IS 'Vista para análisis de validaciones de ejercicios.
Incluye información de ejercicio, usuario, validación, recálculos y discrepancias.
Útil para dashboards de profesores y análisis de calidad de validaciones.';


