    us.total_xp,
    ur.current_rank,
    us.ml_coins,
    us.level,
    count(DISTINCT ua.id) AS achievements_count,
    us.modules_completed,
    us.exercises_completed,
    us.current_streak
   FROM (((auth_management.profiles p
     JOIN gamification_system.user_stats us ON ((p.id = us.user_id)))
     LEFT JOIN gamification_system.user_ranks ur ON (((p.id = ur.user_id) AND (ur.is_current = true))))
     LEFT JOIN gamification_system.user_achievements ua ON ((p.id = ua.user_id)))
  WHERE ((p.role = 'student'::auth_management.gamilit_role) AND (p.status = 'active'::auth_management.user_status))
  GROUP BY p.id, p.full_name, p.avatar_url, us.total_xp, ur.current_rank, us.ml_coins, us.level, us.modules_completed, us.exercises_completed, us.current_streak
  ORDER BY us.total_xp DESC
  WITH NO DATA;


