--
-- TOC entry 486 (class 1259 OID 145628)
-- Name: teacher_pending_reviews; Type: VIEW; Schema: progress_tracking; Owner: gamilit_user
--

CREATE VIEW progress_tracking.teacher_pending_reviews AS
 SELECT es.id AS submission_id,
    es.exercise_id,
    es.user_id AS student_id,
    p.full_name AS student_name,
    p.email AS student_email,
    e.title AS exercise_title,
    e.exercise_type,
    m.title AS module_title,
    m.order_index AS module_order,
    cm.classroom_id,
    c.name AS classroom_name,
    es.score,
    es.time_spent_seconds,
    es.attempt_number,
    es.answer_data,
    es.feedback,
    es.submitted_at,
    es.created_at AS submission_date,
        CASE
            WHEN (es.graded_at IS NOT NULL) THEN 'graded'::text
            WHEN (es.submitted_at IS NOT NULL) THEN 'pending'::text
            ELSE 'in_progress'::text
        END AS review_status,
    es.graded_at,
        CASE
            WHEN (es.submitted_at < (now() - '7 days'::interval)) THEN 'urgent'::text
            WHEN (es.submitted_at < (now() - '3 days'::interval)) THEN 'high'::text
            WHEN (es.submitted_at < (now() - '1 day'::interval)) THEN 'medium'::text
            ELSE 'normal'::text
        END AS priority,
    (EXTRACT(day FROM (now() - es.submitted_at)))::integer AS days_waiting
   FROM (((((progress_tracking.exercise_submissions es
     JOIN auth_management.profiles p ON ((es.user_id = p.id)))
     JOIN educational_content.exercises e ON ((es.exercise_id = e.id)))
     JOIN educational_content.modules m ON ((e.module_id = m.id)))
     LEFT JOIN social_features.classroom_members cm ON (((es.user_id = cm.student_id) AND (cm.is_active = true))))
     LEFT JOIN social_features.classrooms c ON ((cm.classroom_id = c.id)))
  WHERE ((es.graded_at IS NULL) AND (es.submitted_at IS NOT NULL) AND (e.requires_manual_grading = true))
  ORDER BY
        CASE
            WHEN (es.submitted_at < (now() - '7 days'::interval)) THEN 1
            WHEN (es.submitted_at < (now() - '3 days'::interval)) THEN 2
            WHEN (es.submitted_at < (now() - '1 day'::interval)) THEN 3
            ELSE 4
        END, es.submitted_at;


ALTER VIEW progress_tracking.teacher_pending_reviews OWNER TO gamilit_user;

