--
-- TOC entry 406 (class 1259 OID 143453)
-- Name: user_difficulty_progresses; Type: TABLE; Schema: progress_tracking; Owner: postgres
--

CREATE TABLE progress_tracking.user_difficulty_progresses (
    user_id uuid NOT NULL,
    difficulty_level educational_content.difficulty_level NOT NULL,
    exercises_attempted integer DEFAULT 0 NOT NULL,
    exercises_completed integer DEFAULT 0 NOT NULL,
    exercises_correct_first_attempt integer DEFAULT 0 NOT NULL,
    success_rate numeric(5,2) GENERATED ALWAYS AS (
CASE
    WHEN (exercises_attempted > 0) THEN round((((exercises_correct_first_attempt)::numeric / (exercises_attempted)::numeric) * (100)::numeric), 2)
    ELSE (0)::numeric
END) STORED,
    total_time_spent_seconds bigint DEFAULT 0 NOT NULL,
    avg_time_per_exercise numeric(10,2) GENERATED ALWAYS AS (
CASE
    WHEN (exercises_completed > 0) THEN round(((total_time_spent_seconds)::numeric / (exercises_completed)::numeric), 2)
    ELSE (0)::numeric
END) STORED,
    is_ready_for_promotion boolean DEFAULT false NOT NULL,
    promoted_at timestamp with time zone,
    first_attempt_at timestamp with time zone,
    last_attempt_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT gamilit.now_mexico(),
