CREATE TABLE social_features.team_vs_team_challenges (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    title character varying(200) NOT NULL,
    description text,
    challenge_type character varying(50) DEFAULT 'team_vs_team'::character varying,
    team_a_type character varying(50) NOT NULL,
    team_a_id uuid,
    team_a_name character varying(100),
    team_a_members uuid[] NOT NULL,
    team_a_captain_id uuid NOT NULL,
    team_b_type character varying(50),
    team_b_id uuid,
    team_b_name character varying(100),
    team_b_members uuid[],
    team_b_captain_id uuid,
    min_team_size integer DEFAULT 2,
    max_team_size integer DEFAULT 5,
    exercise_ids uuid[],
    module_id uuid,
    time_limit_minutes integer,
    scoring_method character varying(50) DEFAULT 'total_points'::character varying,
    best_n_count integer DEFAULT 3,
    rewards jsonb DEFAULT '{"draw": {"xp": 250, "ml_coins": 50}, "loser": {"xp": 100, "ml_coins": 20}, "winner": {"xp": 500, "ml_coins": 100}}'::jsonb,
    status character varying(50) DEFAULT 'pending'::character varying,
    winner_team character varying(10),
    team_a_score integer DEFAULT 0,
    team_b_score integer DEFAULT 0,
    team_a_accuracy numeric(5,2),
    team_b_accuracy numeric(5,2),
    team_a_avg_time_seconds integer,
    team_b_avg_time_seconds integer,
    results_detail jsonb DEFAULT '{}'::jsonb,
    created_by uuid NOT NULL,
    invitation_expires_at timestamp with time zone,
    accepted_at timestamp with time zone,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT gamilit.now_mexico(),
    updated_at timestamp with time zone DEFAULT gamilit.now_mexico(),
    CONSTRAINT team_vs_team_challenges_challenge_type_check CHECK (((challenge_type)::text = ANY ((ARRAY['team_vs_team'::character varying, 'guild_war'::character varying, 'classroom_battle'::character varying, 'tournament_match'::character varying])::text[]))),
    CONSTRAINT team_vs_team_challenges_dates_valid CHECK ((((starts_at IS NULL) AND (ends_at IS NULL)) OR ((starts_at IS NOT NULL) AND (ends_at IS NOT NULL) AND (starts_at < ends_at)))),
    CONSTRAINT team_vs_team_challenges_max_team_size_check CHECK (((max_team_size >= 1) AND (max_team_size <= 20))),
    CONSTRAINT team_vs_team_challenges_min_max_size CHECK ((min_team_size <= max_team_size)),
    CONSTRAINT team_vs_team_challenges_min_team_size_check CHECK (((min_team_size >= 1) AND (min_team_size <= 20))),
    CONSTRAINT team_vs_team_challenges_scoring_method_check CHECK (((scoring_method)::text = ANY ((ARRAY['total_points'::character varying, 'average'::character varying, 'best_n'::character varying, 'time_based'::character varying, 'accuracy'::character varying])::text[]))),
    CONSTRAINT team_vs_team_challenges_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'accepted'::character varying, 'in_progress'::character varying, 'completed'::character varying, 'cancelled'::character varying, 'expired'::character varying, 'declined'::character varying])::text[]))),
    CONSTRAINT team_vs_team_challenges_team_a_members_not_empty CHECK ((array_length(team_a_members, 1) >= 1)),
    CONSTRAINT team_vs_team_challenges_team_a_type_check CHECK (((team_a_type)::text = ANY ((ARRAY['guild'::character varying, 'classroom'::character varying, 'team'::character varying, 'custom'::character varying])::text[]))),
    CONSTRAINT team_vs_team_challenges_team_b_type_check CHECK (((team_b_type)::text = ANY ((ARRAY['guild'::character varying, 'classroom'::character varying, 'team'::character varying, 'custom'::character varying])::text[]))),
    CONSTRAINT team_vs_team_challenges_time_limit_minutes_check CHECK (((time_limit_minutes IS NULL) OR (time_limit_minutes > 0))),
    CONSTRAINT team_vs_team_challenges_title_length CHECK ((char_length((title)::text) >= 3)),
    CONSTRAINT team_vs_team_challenges_winner_team_check CHECK (((winner_team IS NULL) OR ((winner_team)::text = ANY ((ARRAY['a'::character varying, 'b'::character varying, 'draw'::character varying])::text[]))))
);


